import { useEffect, useState } from "react";
import axios from "axios";

function MisClases({ user }) {
  const [clases, setClases] = useState([]);
  const [loading, setLoading] = useState(true);
  const token = localStorage.getItem("token");

  useEffect(() => {
    const fetchClases = async () => {
      try {
        const res = await axios.get(
          `http://localhost:3000/api/usuarios/${user.id}/clases`,
          { headers: { Authorization: `Bearer ${token}` } }
        );
        setClases(res.data);
      } catch {
        setClases([]);
      } finally {
        setLoading(false);
      }
    };

    fetchClases();
  }, [user.id, token]);

  return (
    <div>
      <h2 className="text-2xl font-bold mb-8 flex items-center gap-2">
        <span className="inline-block w-6 h-6 bg-blue-400 rounded mr-2" />
        Mis Cursos
      </h2>
      {loading ? (
        <div className="text-center">Cargando...</div>
      ) : clases.length === 0 ? (
        <div className="text-center text-gray-500">
          No estás inscrito en ninguna clase.
        </div>
      ) : (
        <div className="flex flex-wrap gap-6">
          {clases.map((clase) => (
            <div
              key={clase.id}
              className="bg-white rounded shadow p-5 w-80 flex flex-col"
            >
              <div className="text-xl font-semibold">{clase.titulo}</div>
              <div className="text-gray-600 mb-3">{clase.descripcion}</div>
              <div className="mb-2">
                <span className="font-semibold">Curso:</span> {clase.curso_nombre}
              </div>
              <div className="mb-2">
                <span className="font-semibold">Fecha:</span> {clase.fecha}
              </div>
              <div className="mb-2">
                <span className="font-semibold">Hora:</span> {clase.hora}
              </div>
              {/* Botón futuro para ingresar a la clase */}
              <button className="bg-green-600 hover:bg-green-700 text-white px-4 py-2 rounded mt-auto">
                Entrar a la clase
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}

export default MisClases;
